byte[] buffer = File.ReadAllBytes("document.pdf");

// Create a Span over the entire buffer — no copy
Span<byte> data = buffer;

// Slice into header, body, and footer — still no allocation
Span<byte> header = data.Slice(0, 4);
Span<byte> body = data.Slice(4, data.Length - 8);
Span<byte> footer = data.Slice(data.Length - 4, 4);

// Parse an integer from the header directly from memory
int fileType = BitConverter.ToInt32(header);
Console.WriteLine($"File type: 0x{fileType:X8}");

// Span works with strings via ReadOnlySpan<char>
ReadOnlySpan<char> text = "Hello, Span<T>".AsSpan();
ReadOnlySpan<char> word = text.Slice(7, 4);
Console.WriteLine(word.ToString()); // Span

// Allocate 128 bytes on the stack
Span<byte> stackBuffer = stackalloc byte[128];

// Fill the buffer with random bytes
Random.Shared.NextBytes(stackBuffer);

// Write the buffer to a file asynchronously
await File.WriteAllBytesAsync("random.bin", stackBuffer.ToArray());
// stackBuffer is reclaimed automatically here

// Parsing a number from a stack-allocated char buffer
Span<char> digits = stackalloc char[10];
int length = int.TryParse("12345", digits, out int parsed);
Console.WriteLine($"Parsed {length} chars: {parsed}");

public async Task ProcessChunkAsync(Memory<byte> chunk)
{
    // Memory<T> can be stored in fields, passed to async methods
    // Access the Span when ready to work
    Span<byte> span = chunk.Span;

    // Process synchronously (CPU-bound)
    int checksum = ComputeChecksum(span);

    // Write asynchronously (I/O-bound)
    await _stream.WriteAsync(chunk);
}

